export const IL4_GENERATION_NOTES = [
  "This file was generated in memory from saved Control Freak project data. It is not stored as an official document version.",
  "Word refreshes the table of contents and page numbers when the document is opened. Substantive content does not depend on that refresh.",
] as const;

export function populationExplanation(counts: {
  totalFrameworkItems: number;
  detailedGrrCount: number;
  detailedNistCount: number;
  membershipNoteCount: number;
  notReprintedCount: number;
}): string {
  const noteLabel =
    counts.membershipNoteCount === 1 ? "membership note" : "membership notes";
  return [
    `The Control Freak IL4 authoring framework contains ${counts.totalFrameworkItems} items.`,
    `This addendum presents the DoD delta: ${counts.detailedGrrCount} General Readiness Requirements and ${counts.detailedNistCount} NIST controls or enhancements in detail, plus ${counts.membershipNoteCount} ${noteLabel}.`,
    `${counts.notReprintedCount} FedRAMP Moderate items are not reprinted here. They remain part of the IL4 authoring framework and of the broader System Security Plan. They are not out of scope for the system.`,
  ].join(" ");
}
